import test from 'node:test';
import assert from 'node:assert/strict';
import {readBudget,subscriptionEvidence,ACCOUNT,BRANCH,ENDPOINTS} from './probe.mjs';
const env={GITHUB_ACTIONS:'true',GITHUB_REPOSITORY:'gradient30/laboratory',GITHUB_REF:`refs/heads/${BRANCH}`,GITHUB_EVENT_NAME:'push',GITHUB_RUN_ATTEMPT:'1',BUDGET_READ_APPROVAL:'owner-approved-readonly-20261028',CLOUDFLARE_ACCOUNT_ID:ACCOUNT,CLOUDFLARE_API_TOKEN:'SYNTHETIC_NOT_A_REAL_TOKEN'};
for(const [key,value] of Object.entries({GITHUB_ACTIONS:'false',GITHUB_REPOSITORY:'other/repo',GITHUB_REF:'refs/heads/main',GITHUB_EVENT_NAME:'pull_request',GITHUB_RUN_ATTEMPT:'2',BUDGET_READ_APPROVAL:'missing',CLOUDFLARE_ACCOUNT_ID:'other',CLOUDFLARE_API_TOKEN:''}))test(`reject invalid ${key} before network`,async()=>{await assert.rejects(readBudget({env:{...env,[key]:value},fetchImpl:()=>assert.fail('no network')}));});
test('only three exact GET endpoints and minimal sanitized fields',async()=>{const seen=[];const result=await readBudget({env,fetchImpl:async(url,opts)=>{seen.push(url);assert.equal(opts.method,'GET');assert.equal(opts.redirect,'error');assert.equal(opts.headers.Authorization,`Bearer ${env.CLOUDFLARE_API_TOKEN}`);const result=url===ENDPOINTS.account?{default_usage_model:'standard',email:'PRIVATE'}:url===ENDPOINTS.worker?{usage_model:'standard',limits:{cpu_ms:30000},bindings:[{text:'PRIVATE'}]}:[{rate_plan:{id:'workers_standard_paid'},state:'Paid',price:123,email:'PRIVATE'},{rate_plan:{id:'unrelated'},state:'Paid'}];return new Response(JSON.stringify({success:true,result}));}});assert.deepEqual(seen,Object.values(ENDPOINTS));const text=JSON.stringify(result);assert(!text.includes('PRIVATE'));assert(!text.includes('123'));assert(!text.includes('SYNTHETIC'));assert.equal(result.worker.configuredCpuMs,30000);assert.deepEqual(result.subscriptions.workersPlans,[{plan:'workers_standard_paid',state:'Paid'}]);});
test('403 is not retried or printed',async()=>{let calls=0;const result=await readBudget({env,fetchImpl:async()=>{calls++;return new Response('sensitive body',{status:403});}});assert.equal(calls,3);assert.equal(result.subscriptions.httpStatus,403);assert(!JSON.stringify(result).includes('sensitive'));});
test('network errors sanitized',async()=>{const result=await readBudget({env,fetchImpl:async()=>{throw Error('sensitive token');}});assert(!JSON.stringify(result).includes('sensitive'));});
test('unknown plan never inferred free/paid',()=>{assert.equal(subscriptionEvidence([]).status,'no-recognized-workers-product-not-proof-of-free');assert.deepEqual(subscriptionEvidence([{rate_plan:{id:'private unusual id'}}]).workersPlans,[]);});
test('unknown fields rejected from output',async()=>{const result=await readBudget({env,fetchImpl:async()=>new Response(JSON.stringify({success:true,result:{usage_model:'SECRET',limits:{cpu_ms:-1},default_usage_model:'SECRET'}}))});assert.equal(result.worker.configuredCpuMs,null);assert.equal(result.worker.usageModel,null);assert(!JSON.stringify(result).includes('SECRET'));});
